INSERT INTO contacts(company_id,fio,phone,email,created_at,updated_at) SELECT m.id,s.fio,s.phone,s.email,now(),now() FROM imp_contact s JOIN imp_company_map m ON m.key=s.company_key WHERE NOT EXISTS(SELECT 1 FROM contacts c WHERE c.company_id=m.id AND c.phone IS NOT DISTINCT FROM s.phone AND c.email IS NOT DISTINCT FROM s.email);
