INSERT INTO deals(id,company_id,service_type,goal_option_id,goal_achieved,called_today,next_call_date,comment,prospective,kanban_stage,activity_date,daily_sequence,week_id,created_by_id,document_intent,next_action,created_at,updated_at) SELECT s.id,m.id,s.service_type,g.id,s.goal_achieved,s.called_today,s.next_call_date,s.comment,s.kanban_stage='PROSPECTIVE',s.kanban_stage,s.activity_date,COALESCE((SELECT max(d.daily_sequence) FROM deals d WHERE d.created_by_id=1 AND d.activity_date=s.activity_date),0)+row_number() OVER(PARTITION BY s.activity_date ORDER BY s.source_no),w.id,1,'NONE',s.next_action,now(),now() FROM imp_deal s JOIN imp_company_map m ON m.key=s.company_key LEFT JOIN goal_options g ON lower(g.name)=lower(s.goal) JOIN weeks w ON w.iso_year=extract(isoyear from s.activity_date) AND w.iso_week_number=extract(week from s.activity_date);
INSERT INTO audit_logs(entity_type,entity_id,field_name,new_value,author_id,created_at,updated_at) SELECT 'DEAL',id,'EXCEL_IMPORT',source_key,1,now(),now() FROM imp_deal;
CREATE TEMP TABLE imp_target (source_no int,city text) ON COMMIT DROP;
