INSERT INTO shifts(city_id,week_id,status,a4_sold,failure_reason,created_at,updated_at) SELECT c.id,w.id,s.status,s.a4_sold,'Excel: '||s.source||'; исходное значение: '||s.raw||'; цвет #'||s.color,now(),now() FROM imp_shift s JOIN cities c ON lower(c.name)=lower(s.city) JOIN weeks w ON w.iso_year=extract(isoyear from s.date) AND w.iso_week_number=extract(week from s.date) WHERE NOT EXISTS(SELECT 1 FROM shifts t WHERE t.city_id=c.id AND t.week_id=w.id);
CREATE TEMP TABLE imp_company_history (key text,note text) ON COMMIT DROP;
