DO $$ BEGIN IF (SELECT count(*) FROM imp_deal s JOIN deals d ON d.id=s.id)<>2626 THEN RAISE EXCEPTION 'Deal count mismatch'; END IF; IF (SELECT count(*) FROM imp_company_map)<>1340 THEN RAISE EXCEPTION 'Company map mismatch'; END IF; IF EXISTS (SELECT 1 FROM imp_deal s JOIN deals d ON d.id=s.id JOIN weeks w ON w.id=d.week_id WHERE d.activity_date NOT BETWEEN w.start_date AND w.end_date) THEN RAISE EXCEPTION 'Week date mismatch'; END IF; END $$;
COMMIT;
SELECT 'companies' entity,count(*) FROM companies UNION ALL SELECT 'contacts',count(*) FROM contacts UNION ALL SELECT 'deals',count(*) FROM deals UNION ALL SELECT 'cities',count(*) FROM cities UNION ALL SELECT 'shifts',count(*) FROM shifts;
